1	use std::env;
2	use std::ffi::{OsStr, OsString};
3	use std::fs;
4	use std::io::Read;
5	use std::path::Path;
6	use std::process::ExitCode;
7	
8	use roottrace::{
9	    claims_json, hex, hex_nibble, inspect_proof, is_lower_hex, split_records, RootStream,
10	};
11	
12	const VERSION: &str = "0.1.0";
13	
14	const USAGE: &str = "\
15	Usage:
16	    roottrace root <file>
17	    roottrace prove <file> <record-index>
18	    roottrace inspect <proof-file>
19	    roottrace verify <record-file> <proof-file> <trusted-tree-size> <trusted-root>
20	    roottrace --version
21	
22	Commands:
23	    root <file>
24	        Print the SHA-256 RFC 6962 Merkle Tree Hash of all records in <file>
25	        as one line of 64 lowercase hexadecimal characters.
26	
27	    prove <file> <record-index>
28	        Print the RFC 6962 section 2.1.1 inclusion (membership) proof for the
29	        record at <record-index> within the whole batch. The index is
30	        0-based and counts records in file order: 0 is the first record,
31	        1 the second, and so on; the same content at multiple positions gets
32	        the proof for the exact position given, with no deduplication. Output
33	        is one JSON object with the fields tree_size, leaf_index, root and
34	        audit_path (leaf-to-root hashes, lowercase hex; empty for a batch of
35	        exactly one record).
36	
37	        Example:
38	            roottrace prove batch.txt 0
39	
40	    inspect <proof-file>
41	        Read one inclusion proof and display the batch size, record position
42	        and root the proof itself claims, without needing the target record
43	        or any independently trusted values. Output is one JSON object with
44	        only the fields tree_size, leaf_index and root. This does NOT verify
45	        membership: the displayed values come from the proof itself, are not
46	        checked against anything, and must not be reused as the trusted
47	        tree size/root arguments of `verify`. A well-formed proof whose
48	        audit_path cannot establish the claimed position is still displayed.
49	
50	        Example:
51	            roottrace inspect proof.json
52	
53	    verify <record-file> <proof-file> <trusted-tree-size> <trusted-root>
54	        Verify an inclusion proof produced by `prove` without needing the
55	        whole batch. The record file holds the raw bytes of exactly one
56	        target record (no LF splitting, byte for byte including any trailing
57	        LF/space/CR, NUL and non-UTF-8 bytes; an empty file is one empty
58	        record). The proof is read as one complete JSON object. The trusted
59	        tree size (an ASCII decimal positive integer) and the trusted root
60	        (64 lowercase hexadecimal characters) must be confirmed
61	        independently; they are never taken from fields inside the proof.
62	        On success stdout is exactly \"verified\\n\", stderr is empty and the
63	        exit status is 0.
64	
65	        Example:
66	            roottrace verify record.bin proof.json 9 a8a3e76e...723adc3
67	
68	Exit status:
69	    0  success
70	    1  an input file cannot be read, the proof is malformed, or verification fails
71	    2  usage error (unknown command, missing or extra arguments, bad arguments)";
72	
73	fn main() -> ExitCode {
74	    // Raw OS arguments: file paths are handed to the filesystem exactly as
75	    // received, byte for byte. On Unix a path may contain bytes that are not
76	    // valid UTF-8 (e.g. 0xff); such a path is not invalid and must reach the
77	    // file rather than aborting argument collection. The command name, the
78	    // record index and the trusted tree size/root arguments are required to
79	    // be UTF-8 text.
80	    let args: Vec<OsString> = env::args_os().skip(1).collect();
81	    match args.as_slice() {
82	        [flag] if flag == OsStr::new("--version") => {
83	            println!("roottrace {VERSION}");
84	            ExitCode::SUCCESS
85	        }
86	        [cmd, path] if cmd == OsStr::new("root") => match merkle_root_of_file(Path::new(path)) {
87	            Ok(root) => {
88	                println!("{}", hex(&root));
89	                ExitCode::SUCCESS
90	            }
91	            Err(reason) => {
92	                eprintln!("roottrace: {reason}");
93	                ExitCode::FAILURE
94	            }
95	        },
96	        [cmd, path, index] if cmd == OsStr::new("prove") => match parse_index(index) {
97	            Some(index) => match proof_for_file(Path::new(path), index) {
98	                Ok(proof) => {
99	                    println!("{}", proof);
100	                    ExitCode::SUCCESS
101	                }
102	                Err(ProveError::Read(reason)) => {
103	                    eprintln!("roottrace: {reason}");
104	                    ExitCode::FAILURE
105	                }
106	                Err(ProveError::Missing(index, size)) => {
107	                    if size == 0 {
108	                        eprintln!(
109	                            "roottrace: record index {index} does not exist: the file holds zero records"
110	                        );
111	                    } else {
112	                        eprintln!(
113	                            "roottrace: record index {index} does not exist: file holds {size} record(s), valid indices are 0 through {}",
114	                            size - 1
115	                        );
116	                    }
117	                    ExitCode::FAILURE
118	                }
119	            },
120	            None => {
121	                let shown = index.to_string_lossy();
122	                eprintln!("roottrace: invalid record index '{shown}': expected a decimal non-negative integer of ASCII digits");
123	                eprintln!("{USAGE}");
124	                ExitCode::from(2)
125	            }
126	        },
127	        [cmd, proof_path] if cmd == OsStr::new("inspect") => {
128	            match inspect_file(Path::new(proof_path)) {
129	                Ok(line) => {
130	                    println!("{line}");
131	                    ExitCode::SUCCESS
132	                }
133	                Err(InspectError::Read { path, source }) => {
134	                    eprintln!(
135	                        "roottrace: cannot read '{}': {source}",
136	                        display_path(&path)
137	                    );
138	                    ExitCode::FAILURE
139	                }
140	                Err(InspectError::MalformedProof(reason)) => {
141	                    eprintln!("roottrace: invalid proof: {reason}");
142	                    ExitCode::FAILURE
143	                }
144	            }
145	        }
146	        [cmd, path, proof_path, size_arg, root_arg] if cmd == OsStr::new("verify") => {
147	            match (parse_trusted_size(size_arg), parse_trusted_root(root_arg)) {
148	                (Some(trusted_size), Some(trusted_root)) => {
149	                    match verify_files(Path::new(path), Path::new(proof_path), trusted_size, &trusted_root) {
150	                        Ok(()) => {
151	                            println!("verified");
152	                            ExitCode::SUCCESS
153	                        }
154	                        Err(VerifyError::Read { path, source }) => {
155	                            eprintln!(
156	                                "roottrace: cannot read '{}': {source}",
157	                                display_path(&path)
158	                            );
159	                            ExitCode::FAILURE
160	                        }
161	                        Err(VerifyError::MalformedProof(reason)) => {
162	                            eprintln!("roottrace: invalid proof: {reason}");
163	                            ExitCode::FAILURE
164	                        }
165	                        Err(VerifyError::Failed(reason)) => {
166	                            eprintln!("roottrace: verification failed: {reason}");
167	                            ExitCode::FAILURE
168	                        }
169	                    }
170	                }
171	                (bad_size, bad_root) => {
172	                    if bad_size.is_none() {
173	                        let shown = size_arg.to_string_lossy();
174	                        eprintln!(
175	                            "roottrace: invalid trusted tree size '{shown}': expected an ASCII decimal positive integer within unsigned 64-bit range"
176	                        );
177	                    }
178	                    if bad_root.is_none() {
179	                        let shown = root_arg.to_string_lossy();
180	                        eprintln!(
181	                            "roottrace: invalid trusted root '{shown}': expected exactly 64 lowercase hexadecimal characters"
182	                        );
183	                    }
184	                    eprintln!("{USAGE}");
185	                    ExitCode::from(2)
186	                }
187	            }
188	        }
189	        _ => {
190	            eprintln!("{USAGE}");
191	            ExitCode::from(2)
192	        }
193	    }
194	}
195	
196	enum ProveError {
197	    Read(String),
198	    Missing(u64, u64),
199	}
200	
201	/// Failures reported by `inspect`, kept separate so an unreadable proof file
202	/// and a well-readable but malformed proof both exit 1 while saying different
203	/// things on stderr.
204	enum InspectError {
205	    /// The proof path cannot be read (missing, a directory, ...).
206	    Read { path: std::path::PathBuf, source: std::io::Error },
207	    /// The proof bytes are not a well-formed proof object.
208	    MalformedProof(String),
209	}
210	
211	/// Failures reported by `verify`, kept separate so that malformed proofs and
212	/// cryptographic mismatches both exit 1 but say different things on stderr.
213	enum VerifyError {
214	    /// One of the two input paths cannot be read (missing, a directory, ...).
215	    Read { path: std::path::PathBuf, source: std::io::Error },
216	    /// The proof bytes are not a well-formed proof object.
217	    MalformedProof(String),
218	    /// The proof is well-formed but does not establish the claimed inclusion
219	    /// against the independently trusted tree size and root.
220	    Failed(String),
221	}
222	
223	/// Read the two input files and run an RFC 6962 inclusion check. The record
224	/// file's ENTIRE byte content is the target record: no LF splitting and no
225	/// trimming of trailing LF, space or CR; NUL and non-UTF-8 bytes take part as
226	/// they are. A zero-byte file is one empty record. The check itself is the
227	/// library entry point `roottrace::verify_membership`, so the command and
228	/// Rust callers of the library share exactly one verification path.
229	fn verify_files(
230	    record_path: &Path,
231	    proof_path: &Path,
232	    trusted_size: u64,
233	    trusted_root: &[u8; 32],
234	) -> Result<(), VerifyError> {
235	    let record = fs::read(record_path).map_err(|source| VerifyError::Read {
236	        path: record_path.to_path_buf(),
237	        source,
238	    })?;
239	    let proof_bytes = fs::read(proof_path).map_err(|source| VerifyError::Read {
240	        path: proof_path.to_path_buf(),
241	        source,
242	    })?;
243	    match roottrace::verify_membership(&record, &proof_bytes, trusted_size, trusted_root) {
244	        Ok(_) => Ok(()),
245	        Err(roottrace::VerifyError::MalformedProof(reason)) => {
246	            Err(VerifyError::MalformedProof(reason))
247	        }
248	        Err(roottrace::VerifyError::VerificationFailed(reason)) => Err(VerifyError::Failed(reason)),
249	        // parse_trusted_size rejects zero before this function is ever
250	        // called, so the library's invalid-argument case cannot occur here.
251	        Err(roottrace::VerifyError::InvalidTrustedSize) => {
252	            unreachable!("the command line only accepts a positive trusted tree size")
253	        }
254	    }
255	}
256	
257	/// Parse the trusted tree size given on the command line: one or more ASCII
258	/// decimal digits naming a POSITIVE 64-bit unsigned integer. Unlike a record
259	/// index, zero is not accepted (it cannot be a tree that contains a record).
260	/// Anything else (sign, whitespace, non-UTF-8 bytes, a value above u64::MAX)
261	/// is a usage error.
262	fn parse_trusted_size(arg: &OsStr) -> Option<u64> {
263	    let text = arg.to_str()?;
264	    if text.is_empty() || !text.bytes().all(|b| b.is_ascii_digit()) {
265	        return None;
266	    }
267	    let mut value: u64 = 0;
268	    for b in text.bytes() {
269	        value = value.checked_mul(10)?.checked_add(u64::from(b - b'0'))?;
270	    }
271	    if value == 0 {
272	        return None;
273	    }
274	    Some(value)
275	}
276	
277	/// Parse the trusted root given on the command line: exactly 64 lowercase
278	/// ASCII hexadecimal characters (32 bytes). Uppercase, wrong length, non-hex
279	/// or non-UTF-8 bytes are usage errors.
280	fn parse_trusted_root(arg: &OsStr) -> Option<[u8; 32]> {
281	    let text = arg.to_str()?;
282	    if text.len() != 64 || !text.bytes().all(is_lower_hex) {
283	        return None;
284	    }
285	    let bytes = text.as_bytes();
286	    let mut out = [0u8; 32];
287	    for (i, pair) in bytes.chunks_exact(2).enumerate() {
288	        out[i] = (hex_nibble(pair[0])? << 4) | hex_nibble(pair[1])?;
289	    }
290	    Some(out)
291	}
292	
293	/// Render a path for a human-readable error message. This is used ONLY in
294	/// diagnostics: the filesystem is always given the raw `Path`, never this
295	/// lossy rendering, so a file whose name contains 0xff is not confused with a
296	/// differently named file that merely displays the same way.
297	fn display_path(path: &Path) -> String {
298	    path.to_string_lossy().into_owned()
299	}
300	
301	/// Compute the batch root by streaming the file through a fixed-size buffer.
302	/// The whole file is never held in memory: each record is hashed as its bytes
303	/// arrive (a record of any length is never stored), and the only state kept
304	/// across records is `RootStream`'s subtree stack of at most 64 hashes —
305	/// O(log n) in the record count, independent of the file's byte size and of
306	/// the longest record. The root printed for a batch is exactly the one the
307	/// previous whole-file implementation computed (and the one `prove` still
308	/// commits to), because `RootStream` folds the same RFC 6962 tree as `mth`.
309	fn merkle_root_of_file(path: &Path) -> Result<[u8; 32], String> {
310	    let mut file = fs::File::open(path)
311	        .map_err(|e| format!("cannot read '{}': {e}", display_path(path)))?;
312	    // Fixed read buffer: how many bytes one read returns cannot affect the
313	    // result — read boundaries are never record boundaries.
314	    let mut buf = [0u8; 64 * 1024];
315	    let mut stream = RootStream::new();
316	    loop {
317	        match file.read(&mut buf) {
318	            Ok(0) => break,
319	            Ok(n) => stream.feed(&buf[..n]),
320	            Err(e) if e.kind() == std::io::ErrorKind::Interrupted => continue,
321	            // A failure partway through (including a directory path, whose
322	            // open succeeds but whose read fails) aborts the whole command:
323	            // the partial batch read so far is never reported as a root.
324	            Err(e) => return Err(format!("cannot read '{}': {e}", display_path(path))),
325	        }
326	    }
327	    Ok(stream.finish())
328	}
329	
330	fn proof_for_file(path: &Path, index: u64) -> Result<String, ProveError> {
331	    let data = fs::read(path)
332	        .map_err(|e| ProveError::Read(format!("cannot read '{}': {e}", display_path(path))))?;
333	    let records = split_records(&data);
334	    // The generation itself is the library entry point
335	    // `roottrace::prove_membership`, so the command and Rust callers of the
336	    // library share exactly one proof-generation path.
337	    match roottrace::prove_membership(&records, index) {
338	        Ok(proof) => Ok(proof.to_json()),
339	        Err(roottrace::ProveError::IndexOutOfRange {
340	            requested_index,
341	            tree_size,
342	        }) => Err(ProveError::Missing(requested_index, tree_size)),
343	    }
344	}
345	
346	/// Read a proof file and return the one-line JSON object `inspect` prints:
347	/// only tree_size, leaf_index and root, taken straight from the proof. The
348	/// proof is parsed with the SAME full format check `verify` uses — a damaged
349	/// audit_path, a duplicate field, a zero tree size or an out-of-range index
350	/// are all rejected — but no target record and no trusted values exist here,
351	/// so no membership check is run and the returned text never says "verified".
352	fn inspect_file(path: &Path) -> Result<String, InspectError> {
353	    let proof_bytes = fs::read(path).map_err(|source| InspectError::Read {
354	        path: path.to_path_buf(),
355	        source,
356	    })?;
357	    let claims = match inspect_proof(&proof_bytes) {
358	        Ok(claims) => claims,
359	        Err(roottrace::InspectError::MalformedProof(reason)) => {
360	            return Err(InspectError::MalformedProof(reason));
361	        }
362	    };
363	    Ok(claims_json(&claims))
364	}
365	
366	/// Parse a record index: one or more ASCII decimal digits, non-negative, no
367	/// sign or whitespace, fitting in an unsigned 64-bit integer. Anything else
368	/// (including "+1", " 1", "1.0", "", "-1", or an argument that is not valid
369	/// UTF-8) is rejected as a usage error.
370	fn parse_index(arg: &OsStr) -> Option<u64> {
371	    let text = arg.to_str()?;
372	    if text.is_empty() || !text.bytes().all(|b| b.is_ascii_digit()) {
373	        return None;
374	    }
375	    let mut value: u64 = 0;
376	    for b in text.bytes() {
377	        value = value.checked_mul(10)?.checked_add(u64::from(b - b'0'))?;
378	    }
379	    Some(value)
380	}
381	
382	#[cfg(test)]
383	mod tests {
384	    use super::*;
385	    use std::os::unix::ffi::OsStrExt;
386	
387	    #[test]
388	    fn index_parsing_accepts_only_ascii_unsigned_decimal() {
389	        assert_eq!(parse_index(OsStr::new("0")), Some(0));
390	        assert_eq!(parse_index(OsStr::new("00")), Some(0));
391	        assert_eq!(parse_index(OsStr::new("123")), Some(123));
392	        assert_eq!(parse_index(OsStr::new("18446744073709551615")), Some(u64::MAX));
393	        assert_eq!(parse_index(OsStr::new("18446744073709551616")), None);
394	        assert_eq!(parse_index(OsStr::new("")), None);
395	        assert_eq!(parse_index(OsStr::new("-1")), None);
396	        assert_eq!(parse_index(OsStr::new("+1")), None);
397	        assert_eq!(parse_index(OsStr::new("1.0")), None);
398	        assert_eq!(parse_index(OsStr::new(" 1")), None);
399	        assert_eq!(parse_index(OsStr::new("1 ")), None);
400	        assert_eq!(parse_index(OsStr::new("0x1")), None);
401	        assert_eq!(parse_index(OsStr::new("①")), None);
402	        // Leading-zero overflow is still overflow.
403	        assert_eq!(parse_index(OsStr::new("0018446744073709551616")), None);
404	        // An argument that is not valid UTF-8 is a usage error, never a panic.
405	        assert_eq!(parse_index(OsStr::from_bytes(b"1\xff")), None);
406	        assert_eq!(parse_index(OsStr::from_bytes(b"\xff")), None);
407	    }
408	
409	    // --- trusted command-line arguments -------------------------------------
410	
411	    #[test]
412	    fn trusted_size_accepts_only_positive_ascii_decimal_u64() {
413	        assert_eq!(parse_trusted_size(OsStr::new("1")), Some(1));
414	        assert_eq!(parse_trusted_size(OsStr::new("09")), Some(9));
415	        assert_eq!(parse_trusted_size(OsStr::new("18446744073709551615")), Some(u64::MAX));
416	        // Zero is not a tree that can contain a record.
417	        assert_eq!(parse_trusted_size(OsStr::new("0")), None);
418	        assert_eq!(parse_trusted_size(OsStr::new("00")), None);
419	        for bad in ["", "-1", "+1", "1.0", " 1", "1 ", "0x1", "18446744073709551616", "①"] {
420	            assert_eq!(parse_trusted_size(OsStr::new(bad)), None, "size {bad:?}");
421	        }
422	        assert_eq!(parse_trusted_size(OsStr::from_bytes(b"9\xff")), None);
423	    }
424	
425	    #[test]
426	    fn trusted_root_accepts_exactly_64_lowercase_hex() {
427	        let h = hex(&roottrace::mth(&[b"a"]));
428	        let parsed = parse_trusted_root(OsStr::new(&h)).expect("valid root");
429	        assert_eq!(parsed, roottrace::mth(&[b"a"]));
430	        for bad in [
431	            "",
432	            &"a".repeat(63),
433	            &"a".repeat(65),
434	            // One uppercase digit.
435	            &{
436	                let mut s = h.clone();
437	                s.replace_range(0..1, "A");
438	                s
439	            },
440	            &format!("{h} "),
441	            &format!(" {h}"),
442	            &"z".repeat(64),
443	        ] {
444	            assert!(parse_trusted_root(OsStr::new(bad)).is_none(), "root {bad:?}");
445	        }
446	        assert!(parse_trusted_root(OsStr::from_bytes(&[b'a'; 65])).is_none());
447	    }
448	}
