1	//! End-to-end regression tests for `roottrace root` on batches where one
2	//! record spans MULTIPLE reads of the file: `root` streams the file through a
3	//! fixed 64 KiB buffer, and the batch built here holds a 140000-byte record
4	//! (> 128 KiB) whose bytes arrive in several separate reads, plus two
5	//! record-separating LFs placed exactly on the last/first byte of a read
6	//! boundary. A read boundary must never become a record boundary: the long
7	//! record participates as its full byte sequence exactly once, and no record
8	//! is truncated, counted twice, or split into several positions.
9	//!
10	//! Expected roots are FIXED constants produced independently of roottrace by
11	//! `tests/reference/rfc6962_multiread_vectors.py` (standard-library
12	//! `hashlib.sha256`, the RFC 6962 recursive definition and an order-sensitive
13	//! stack fold agreeing); they are never derived from roottrace output. The
14	//! record bytes are rebuilt here with the same deterministic construction as
15	//! that script, so the expected root is anchored to the exact record sequence
16	//! documented below.
17	//!
18	//! The batch (10 records, a non-power-of-two count; RFC 6962 splits k=8, so
19	//! the long record at position 4 sits in the left subtree and the trailing
20	//! short record at position 9 in the right one):
21	//!
22	//! ```text
23	//!   0  "alpha"        short; duplicated byte-for-byte at position 6
24	//!   1  ""             empty record
25	//!   2  PAD            65528 bytes ("pad:" + 'p' * 65524); its terminating LF
26	//!                     is the LAST byte of the first 64 KiB read (offset 65535)
27	//!   3  ""             empty record; its LF is the FIRST byte of the second
28	//!                     read (offset 65536) - two consecutive LFs straddle the
29	//!                     read boundary and each still terminates one record
30	//!   4  LONG           140000 bytes (> 128 KiB), spanning reads 1..3; NUL, CR
31	//!                     and non-UTF-8 bytes in both halves and at the tail
32	//!   5  "beta\r"       short, trailing CR is content
33	//!   6  "alpha"        duplicate of position 0 (must not be merged)
34	//!   7  ""             empty record
35	//!   8  "\xff\x00z"    short, non-UTF-8 and NUL bytes
36	//!   9  "end-record\x01"  trailing short record, must reach the final root
37	//! ```
38	
39	mod common;
40	
41	use std::process::Command;
42	
43	use common::{assert_root, bin, join_lf, TempFile};
44	
45	/// The fixed buffer `roottrace root` reads the file through (src/main.rs).
46	/// The batch below is laid out against this size so that record separators
47	/// land exactly on a read boundary.
48	const READ_BUF: usize = 64 * 1024;
49	
50	/// Length of the long record: > 128 KiB, so it spans several consecutive
51	/// reads no matter where in the file it starts.
52	const LONG_LEN: usize = 140_000;
53	
54	/// Length of the PAD record: 7 bytes precede it in the file ("alpha\n" and
55	/// the empty record's "\n"), so PAD's terminating LF is the last byte of the
56	/// first read (offset READ_BUF - 1 = 65535).
57	const PAD_LEN: usize = READ_BUF - 1 - 7; // 65528
58	
59	/// Position of the single changed content byte inside the long record: in
60	/// its second half and, as a file offset (65537 + 100000 = 165537), inside a
61	/// later read than the record's first bytes.
62	const MOD_POS: usize = 100_000;
63	
64	// Independently fixed RFC 6962 roots
65	// (tests/reference/rfc6962_multiread_vectors.py).
66	const ROOT_MREAD: &str = "dca3d078542c8497a09302a4a0cd3b521a498ce3bffbe29bf9f510f2d1203304";
67	const ROOT_MREAD_M: &str = "93011d0e8ec828d5c3fd2698f87664fcdb9ce07f4b16bb5cac269474478d3f57";
68	
69	/// Deterministic pseudo-random content byte; LF is remapped so the long
70	/// record never contains its own separator. Identical to `fill_byte` in
71	/// tests/reference/rfc6962_multiread_vectors.py.
72	fn fill_byte(i: usize) -> u8 {
73	    let b = ((i as u32).wrapping_mul(2_654_435_761) >> 13) as u8;
74	    if b == b'\n' {
75	        0x0b
76	    } else {
77	        b
78	    }
79	}
80	
81	/// The 140000-byte record: pseudo-random binary fill with a distinct marker
82	/// spliced into the first half, the second half and the tail, so each region
83	/// carries content that distinguishes the original bytes.
84	fn long_record() -> Vec<u8> {
85	    let mut rec: Vec<u8> = (0..LONG_LEN).map(fill_byte).collect();
86	    rec[..13].copy_from_slice(b"MREAD\x00\xff\xfe\rHEAD"); // first-half marker
87	    let mid = LONG_LEN / 2;
88	    let marker = b"\x00\xff\rSECOND-HALF"; // second-half marker
89	    rec[mid..mid + marker.len()].copy_from_slice(marker);
90	    let tail = b"\x00TAIL\r\xff"; // tail marker, ends on a non-text byte
91	    rec[LONG_LEN - tail.len()..].copy_from_slice(tail);
92	    rec
93	}
94	
95	/// The same record with exactly ONE non-LF content byte changed at MOD_POS
96	/// in the second half; length and every other byte are kept.
97	fn long_record_m() -> Vec<u8> {
98	    let mut rec = long_record();
99	    let old = rec[MOD_POS];
100	    rec[MOD_POS] = if old != b'A' { b'A' } else { b'B' };
101	    rec
102	}
103	
104	/// The PAD record aligning the following LFs to the read boundary.
105	fn pad_record() -> Vec<u8> {
106	    let mut p = b"pad:".to_vec();
107	    p.resize(PAD_LEN, b'p');
108	    p
109	}
110	
111	/// The 10-record sequence, with the long record (original or modified)
112	/// plugged in at position 4.
113	fn records<'a>(pad: &'a [u8], long: &'a [u8]) -> Vec<&'a [u8]> {
114	    vec![
115	        b"alpha",
116	        b"",
117	        pad,
118	        b"",
119	        long,
120	        b"beta\r",
121	        b"alpha",
122	        b"",
123	        b"\xff\x00z",
124	        b"end-record\x01",
125	    ]
126	}
127	
128	/// Run `roottrace root` on a file holding exactly `file_bytes`.
129	fn run_root(file_bytes: &[u8]) -> std::process::Output {
130	    let tmp = TempFile::create(file_bytes);
131	    Command::new(bin())
132	        .arg("root")
133	        .arg(&tmp.path)
134	        .output()
135	        .expect("failed to execute roottrace binary")
136	}
137	
138	#[test]
139	fn batch_shape_covers_multiple_reads_and_boundary_lfs() {
140	    let pad = pad_record();
141	    let long = long_record();
142	    let recs = records(&pad, &long);
143	
144	    // Non-power-of-two record count with empty records, a duplicate and a
145	    // trailing short record.
146	    assert_eq!(recs.len(), 10);
147	    assert!(!recs.len().is_power_of_two());
148	    assert_eq!(recs[0], recs[6], "duplicate content must not be merged");
149	    assert_eq!(recs[1], b"");
150	    assert_eq!(recs[3], b"");
151	    assert_eq!(recs[7], b"");
152	    assert_eq!(recs[9], b"end-record\x01");
153	
154	    // The long record exceeds 128 KiB and contains no LF; NUL, CR and
155	    // non-UTF-8 bytes appear in both halves and at the tail.
156	    assert!(long.len() > 128 * 1024);
157	    assert!(!long.contains(&b'\n'));
158	    let half = LONG_LEN / 2;
159	    for region in [&long[..half], &long[half..]] {
160	        assert!(region.contains(&0x00), "NUL in each half");
161	        assert!(region.contains(&0x0d), "CR in each half");
162	        assert!(region.iter().any(|&b| b >= 0x80), "non-UTF-8 in each half");
163	    }
164	    assert_eq!(&long[..13], b"MREAD\x00\xff\xfe\rHEAD");
165	    assert_eq!(&long[half..half + 14], b"\x00\xff\rSECOND-HALF");
166	    assert_eq!(&long[LONG_LEN - 7..], b"\x00TAIL\r\xff");
167	
168	    // File layout against the 64 KiB read buffer: the LFs terminating
169	    // records 2 and 3 are consecutive bytes straddling the first read
170	    // boundary, and the long record spans several reads.
171	    let data = join_lf(&recs, true);
172	    assert_eq!(data.len(), 205_567);
173	    assert!(data.len() > 3 * READ_BUF, "the file needs several reads");
174	    assert_eq!(data[READ_BUF - 1], b'\n', "PAD's LF is the last byte of read 0");
175	    assert_eq!(data[READ_BUF], b'\n', "the empty record's LF is the first byte of read 1");
176	    assert_ne!(data[READ_BUF - 2], b'\n');
177	    assert_ne!(data[READ_BUF + 1], b'\n');
178	    let long_start = 7 + PAD_LEN + 1 + 1; // after PAD's LF and record 3's LF
179	    let long_end = long_start + LONG_LEN - 1;
180	    assert_eq!(long_start, READ_BUF + 1);
181	    assert!(
182	        long_end / READ_BUF - long_start / READ_BUF >= 2,
183	        "the long record must span at least three reads"
184	    );
185	    // The file holds exactly ten LFs: nine separators plus the terminator.
186	    assert_eq!(data.iter().filter(|&&b| b == b'\n').count(), 10);
187	}
188	
189	#[test]
190	fn multi_read_batch_matches_fixed_root_with_and_without_trailing_lf() {
191	    let pad = pad_record();
192	    let long = long_record();
193	    let recs = records(&pad, &long);
194	
195	    assert_root(
196	        "MREAD: 10 records, 140000-byte record spanning reads, trailing LF",
197	        &recs,
198	        &join_lf(&recs, true),
199	        ROOT_MREAD,
200	    );
201	    assert_root(
202	        "MREAD: same record sequence, no trailing LF",
203	        &recs,
204	        &join_lf(&recs, false),
205	        ROOT_MREAD,
206	    );
207	
208	    // The two file forms encode the same record sequence, so the command
209	    // output must be byte-for-byte identical, not just equal to the vector.
210	    let with_lf = run_root(&join_lf(&recs, true));
211	    let without_lf = run_root(&join_lf(&recs, false));
212	    assert_eq!(with_lf.status.code(), Some(0));
213	    assert_eq!(without_lf.status.code(), Some(0));
214	    assert_eq!(with_lf.stdout, without_lf.stdout);
215	    assert_eq!(with_lf.stdout, format!("{ROOT_MREAD}\n").into_bytes());
216	    assert!(with_lf.stderr.is_empty() && without_lf.stderr.is_empty());
217	}
218	
219	#[test]
220	fn one_byte_change_in_second_half_gives_the_modified_batchs_fixed_root() {
221	    let pad = pad_record();
222	    let long = long_record();
223	    let long_m = long_record_m();
224	
225	    // Exactly one content byte differs, in the second half of the long
226	    // record; it is not an LF, and record count and order are unchanged.
227	    assert!(MOD_POS > LONG_LEN / 2);
228	    assert_eq!(long_m.len(), long.len());
