#define _GNU_SOURCE
#include <dlfcn.h>
#include <errno.h>
#include <unistd.h>
#include <string.h>
#include <stdlib.h>
#include <fcntl.h>
#include <stdio.h>

/* Usage:
   RT_TARGET=<substr in opened path>
   RT_SCRIPT=<read-index actions on the target fd, comma list>
     actions applied in order on successive read() calls on target fd:
       ok    : normal read
       intr  : return -1/EINTR
       io    : return -1/EIO
       once exhausted, normal reads.
*/

typedef ssize_t (*read_fn)(int, void *, size_t);
typedef int (*openat_fn)(int, const char *, int, ...);
static read_fn real_read;
static openat_fn real_openat;

#define MAXFD 4096
static char is_target[MAXFD];
static unsigned long callcnt[MAXFD];
static char script[4096];
static const char *target;

static void ensure_init(void) {
    if (!real_read) {
        real_read = (read_fn)dlsym(RTLD_NEXT, "read");
        real_openat = (openat_fn)dlsym(RTLD_NEXT, "openat");
        target = getenv("RT_TARGET");
        const char *s = getenv("RT_SCRIPT");
        if (s) { strncpy(script, s, sizeof script -1); }
    }
}

static int path_matches(const char *p) {
    if (!target || !p) return 0;
    return strstr(p, target) != NULL;
}

int openat(int dirfd, const char *pathname, int flags, ...) {
    ensure_init();
    mode_t mode = 0;
    if (flags & O_CREAT) {
        va_list ap; va_start(ap, flags); mode = va_arg(ap, mode_t); va_end(ap);
    }
    int fd = real_openat(dirfd, pathname, flags, mode);
    if (fd >= 0 && fd < MAXFD && path_matches(pathname)) is_target[fd] = 1;
    return fd;
}

static int next_action(char *out) {
    static char *save = NULL;
    char *tok;
    if (script[0] == '\0') return 0;
    tok = strtok_r(script, ",", &save);
    if (!tok) return 0;
    /* after first strtok_r with non-NULL first arg, subsequent calls need NULL; emulate */
    return 0;
}

ssize_t read(int fd, void *buf, size_t n) {
    ensure_init();
    if (fd >= 0 && fd < MAXFD && is_target[fd]) {
        unsigned long c = callcnt[fd]++;
        const char *s = getenv("RT_SCRIPT");
        if (s) {
            /* parse c-th token each time cheaply */
            static __thread char local[4096];
            strncpy(local, s, sizeof local -1); local[sizeof local-1]=0;
            char *savep = NULL;
            char *tok = strtok_r(local, ",", &savep);
            unsigned long i = 0;
            while (tok && i < c) { tok = strtok_r(NULL, ",", &savep); i++; }
            if (tok && i == c) {
                if (strcmp(tok, "intr") == 0) { errno = EINTR; return -1; }
                if (strcmp(tok, "io") == 0) { errno = EIO; return -1; }
            }
        }
    }
    return real_read(fd, buf, n);
}
