    // record. Each is a retry of the same position with zero bytes consumed.
    let tmp = TempFile::create(&join_lf(&recs, true));
    let out = root_with_faults(
        &tmp.path,
        &shim,
        "intr,ok,intr,intr,ok,ok,ok,ok,ok,ok",
